-- Verified opportunity research snapshot: 2026-11-20 (Asia/Kolkata)
-- Deadline is TEXT so it can contain YYYY-MM-DD or Rolling. Numeric NULLs mean undisclosed/not applicable.
BEGIN;
CREATE TABLE IF NOT EXISTS verified_companies (
  company_name TEXT PRIMARY KEY,
  company_type TEXT,
  verified_website_or_career_url TEXT,
  description TEXT
);
CREATE TABLE IF NOT EXISTS verified_opportunities (
  opportunity_id BIGSERIAL PRIMARY KEY,
  company_name TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('JOB','INTERNSHIP','HACKATHON','COMPETITION','RESEARCH','TRAINING')),
  title TEXT NOT NULL,
  location TEXT,
  work_mode TEXT,
  experience_level TEXT,
  stipend_ctc_min_inr NUMERIC(14,2),
  stipend_ctc_max_inr NUMERIC(14,2),
  deadline TEXT NOT NULL,
  direct_application_url TEXT,
  source_portal_name TEXT,
  explicitly_listed_skills TEXT,
  short_description TEXT
);
CREATE TABLE IF NOT EXISTS portal_audit (
  portal_url TEXT PRIMARY KEY,
  live_listings_extracted TEXT,
  valid_items_found INTEGER NOT NULL,
  blockers_or_notes TEXT
);
COMMIT;
