INSERT INTO verified_opportunities (company_name, type, title, location, work_mode, experience_level, stipend_ctc_min_inr, stipend_ctc_max_inr, deadline, direct_application_url, source_portal_name, explicitly_listed_skills, short_description) VALUES ('MeitY / IndiaAI Mission', 'RESEARCH', 'IndiaAI Fellowship 2026–27', 'Pan India', 'HYBRID', 'UG, PG, Integrated Dual Degree and PhD students are named as target cohorts; detailed eligibility on listing also specifies Indian nationals in full-time UG study and at least 3 AI-related courses (confirm cohort criteria on official portal)', NULL, NULL, '2026-11-30', 'https://internshala.com/competitions/indiaai-fellowship-2026-27/', 'Internshala Competitions (organiser: MeitY / IndiaAI Mission)', 'Artificial Intelligence, AI, AI/ML', 'Government-backed fellowship for academic year 2026–27; listing says application status Open and deadline 30 Nov 2026, online application and institute-based research, free. Benefits are financial assistance up to ₹1,00,000 for UG/integrated dual degree; up to ₹2,00,000 for PG; PhD stipend ₹70,000/month (years 1–2), ₹75,000/month (year 3), ₹80,000/month (years 4–5), plus research grant up to ₹2,00,000/year. Official fellowship portal was not retrievable in the live fetch; listing’s eligibility summary and detailed bullet are inconsistent, so check current cohort criteria on the official portal https://fellowship.indiaai.gov.in/login.');
