INSERT INTO portal_audit (portal_url, live_listings_extracted, valid_items_found, blockers_or_notes) VALUES ('https://interndoor.com/', 'YES', 0, 'Public India internship/job feed visible (198 internships and 1,357 full-time shown); individual employer application pages could not be verified for shortlisted roles. URL was pasted twice; audited once.');
