INSERT INTO portal_audit (portal_url, live_listings_extracted, valid_items_found, blockers_or_notes) VALUES ('https://www.google.com/about/careers/applications/jobs/results', 'YES', 0, 'Global public search page reported 3,086 jobs, but the supplied default view showed global/US roles; no specific India-eligible software/AI role verified in this audit.');
